use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[j + a@.len()] == b@[j],
{
    let mut res: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a@.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases a@.len() - i as int,
    {
        res.push(a[i]);
        i = i + 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b@.len(),
            res@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            forall|k: int| 0 <= k < j as int ==> res@[k + a@.len()] == b@[k],
        decreases b@.len() - j as int,
    {
        res.push(b[j]);
        j = j + 1;
    }

    res
}

} // verus!